const statusHistory = `-- name: StatusHistory :many
SELECT id, subject, subject_id, from_status, to_status, reason, actor_id, created_at, auto FROM moderation_log WHERE subject = $1 AND subject_id = $2 ORDER BY id
`

type StatusHistoryParams struct {
	Subject   string
	SubjectID int64
}

func (q *Queries) StatusHistory(ctx context.Context, arg StatusHistoryParams) ([]ModerationLog, error) {
	rows, err := q.db.Query(ctx, statusHistory, arg.Subject, arg.SubjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ModerationLog{}
	for rows.Next() {
		var i ModerationLog
		if err := rows.Scan(
			&i.ID,
			&i.Subject,
			&i.SubjectID,
			&i.FromStatus,
			&i.ToStatus,
			&i.Reason,
			&i.ActorID,
			&i.CreatedAt,
			&i.Auto,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const submitStatsSince = `-- name: SubmitStatsSince :one
SELECT count(*)::int AS sent, COALESCE(min(created_at), now())::timestamptz AS first_at
FROM moderation_log
WHERE actor_id = $1 AND to_status = 'pending_review' AND created_at > $2
`

type SubmitStatsSinceParams struct {
	ActorID pgtype.Int8
	Since   pgtype.Timestamptz
}

type SubmitStatsSinceRow struct {
	Sent    int32
	FirstAt pgtype.Timestamptz
}

func (q *Queries) SubmitStatsSince(ctx context.Context, arg SubmitStatsSinceParams) (SubmitStatsSinceRow, error) {
	row := q.db.QueryRow(ctx, submitStatsSince, arg.ActorID, arg.Since)
	var i SubmitStatsSinceRow
	err := row.Scan(&i.Sent, &i.FirstAt)
	return i, err
}

